_CODON_TABLES_FILE = _DATA_DIR / "codon_tables.json"
_codon_tables_cache: "list | None" = None

# ── Crash-recovery autosave ────────────────────────────────────────────────────
# Every edit marks the record dirty, which (debounced) writes the current record
# to _CRASH_RECOVERY_DIR/{safe_id}.gb. A successful save or clean-state flip
# deletes the file. On startup we scan the dir and notify the user if any
# leftover autosaves exist (i.e. the last session crashed before save).
_CRASH_RECOVERY_DIR = _DATA_DIR / "crash_recovery"


def _codon_raw_to_json(raw: dict) -> dict:
    """Convert in-memory {codon: (aa, count)} → JSON-safe {codon: [aa, count]}."""
    return {c: [aa, int(n)] for c, (aa, n) in raw.items()}


def _codon_raw_from_json(blob: dict) -> dict:
    """Inverse of _codon_raw_to_json. Accepts either tuples or 2-item lists."""
    out: dict = {}
    for c, v in blob.items():
        if isinstance(v, (list, tuple)) and len(v) == 2:
            out[c.upper()] = (str(v[0]), int(v[1]))
    return out


def _codon_tables_load() -> list[dict]:
    """Load codon-table registry. Returns a deep copy so caller-side
    mutation of the `raw` dict (e.g. an in-progress Kazusa import edit)
    can't poison the cache — matches invariant #17. Seeds built-in
    E. coli K12 on first run so the library is never empty."""
    global _codon_tables_cache
    if _codon_tables_cache is not None:
        return _typed_clone(_codon_tables_cache)
    entries, warning = _safe_load_json(_CODON_TABLES_FILE, "Codon table library")
    if warning:
        _log.warning("Codon table library: %s", warning)
    fixed: list = []
    for e in entries:
        if not isinstance(e, dict):
            continue
        raw = _codon_raw_from_json(e.get("raw", {}))
        if not raw:
            continue
        fixed.append({
            "name":   e.get("name", "?"),
            "taxid":  str(e.get("taxid", "")),
            "source": e.get("source", "user"),
            "added":  e.get("added", ""),
            "raw":    raw,
        })
    # Seed built-in K12 if not present
    if not any(e.get("taxid") == "83333" for e in fixed):
        fixed.insert(0, {
            "name":   "E. coli K12",
            "taxid":  "83333",
            "source": "builtin",
            "added":  _date.today().isoformat(),
            "raw":    dict(_CODON_BUILTIN_K12),
        })
        _codon_tables_cache = fixed
        # Module-level seed path — no `app` context to notify. Log-only
        # so a disk-full first launch surfaces in the log bundle and
        # the cache (in memory) still has the K12 seed.
        try:
            _codon_tables_save(fixed)
        except (OSError, RuntimeError):
            _log.exception("Codon tables: K12 seed save failed (in-memory "
                           "cache populated; disk write deferred)")
    else:
        _codon_tables_cache = fixed
    return _typed_clone(_codon_tables_cache)


def _codon_tables_save(entries: list[dict]) -> None:
    """Persist registry to disk via _safe_save_json (atomic, .bak).
    Re-seats the cache with a deep copy so callers that retain a reference
    to the input list (and continue mutating it) can't leak post-save
    edits into the next reader. Matches invariant #17."""
    global _codon_tables_cache
    serializable = [{
        "name":   e.get("name", "?"),
        "taxid":  str(e.get("taxid", "")),
        "source": e.get("source", "user"),
        "added":  e.get("added", ""),
        "raw":    _codon_raw_to_json(e.get("raw", {})),
    } for e in entries]
    with _cache_lock:
        _safe_save_json(_CODON_TABLES_FILE, serializable, "Codon table library")
        _codon_tables_cache = _typed_clone(entries)


def _codon_tables_add(name: str, taxid: str, raw: dict,
                      source: str = "user") -> dict:
    """Insert or replace a table in the registry. Dedup key is taxid when
    non-empty, else name. Returns the stored entry."""
    entries = _codon_tables_load()
    taxid = str(taxid or "").strip()
    name  = (name or "?").strip() or "?"
    entry = {
        "name":   name,
        "taxid":  taxid,
        "source": source,
        "added":  _date.today().isoformat(),
        "raw":    dict(raw),
    }
    def _same(e):
        if taxid and e.get("taxid") == taxid:
            return True
        if not taxid and e.get("name") == name:
            return True
        return False
    kept = [e for e in entries if not _same(e)]
    kept.append(entry)
    _codon_tables_save(kept)
    return entry


def _codon_tables_get(key: str) -> "dict | None":
    """Look up a table by taxid or name (case-insensitive). Returns the
    in-memory entry (with 'raw' as tuples) or None."""
    key = (key or "").strip().lower()
    if not key:
        return None
    for e in _codon_tables_load():
        if str(e.get("taxid", "")).lower() == key:
            return e
        if str(e.get("name", "")).lower() == key:
            return e
    return None


_CODON_TSV_MAX_CHARS = 1_000_000   # 64 codons; even a verbose export is KB


# Three-letter (and stop-alias) → one-letter for TSV amino-acid columns.
_CODON_TSV_AA3 = {
    "ALA": "A", "ARG": "R", "ASN": "N", "ASP": "D", "CYS": "C",
    "GLN": "Q", "GLU": "E", "GLY": "G", "HIS": "H", "ILE": "I",
    "LEU": "L", "LYS": "K", "MET": "M", "PHE": "F", "PRO": "P",
    "SER": "S", "THR": "T", "TRP": "W", "TYR": "Y", "VAL": "V",
    "STOP": "*", "TER": "*", "END": "*",
}


def _parse_codon_tsv(text: str) -> dict:
    """Parse a tab/whitespace/comma-delimited codon-usage table into the
    in-memory ``{codon: (aa, count)}`` registry shape. Pure — no I/O.

    Each data row needs a 3-base codon and a usage count. An optional
    amino-acid column (1-letter, 3-letter, or ``*`` / ``Stop``) is
    validated against the standard code and otherwise derived from
    ``_CODON_GENETIC_CODE``. Rows whose first token isn't an ACGT/U codon
    (headers), blank lines, and ``#`` comments are skipped. Counts may be
    ints or floats (rounded); a fraction-only row (0..1) is scaled by
    1000 so relative preference survives. ``U`` is accepted and folded to
    ``T``.

    Raises ``ValueError`` with a readable message on a bad codon, a
    non-numeric / negative count, an AA/codon mismatch, a duplicate
    codon, or a file with zero usable rows — callers surface it in a
    status line rather than crashing.
    """
    if not isinstance(text, str):
        raise ValueError("codon table must be text")
    if len(text) > _CODON_TSV_MAX_CHARS:
        raise ValueError("codon table is too large (1 MB cap)")
    raw: "dict[str, tuple[str, int]]" = {}
    for lineno, line in enumerate(text.splitlines(), 1):
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        toks = [t for t in re.split(r"[\s,]+", s) if t]
        if not toks:
            continue
        codon = toks[0].upper().replace("U", "T")
        if len(codon) != 3 or any(b not in "ACGT" for b in codon):
            continue   # header / non-codon row — skip silently
        if codon not in _CODON_GENETIC_CODE:
            raise ValueError(f"line {lineno}: {codon!r} is not a valid codon")
        if codon in raw:
            raise ValueError(f"line {lineno}: duplicate codon {codon!r}")
        expected_aa = _CODON_GENETIC_CODE[codon]
        aa_given: "str | None" = None
        numeric: list[str] = []
        for t in toks[1:]:
            tu = t.upper()
            if len(tu) == 1 and (tu in "ACDEFGHIKLMNPQRSTVWY" or tu in "*.X"):
                aa_given = "*" if tu in "*.X" else tu
            elif tu in _CODON_TSV_AA3:
                aa_given = _CODON_TSV_AA3[tu]
            else:
                try:
                    float(t)
                    numeric.append(t)
                except ValueError:
                    pass   # stray non-numeric, non-AA token — ignore
        if aa_given is not None and aa_given != expected_aa:
            raise ValueError(
                f"line {lineno}: codon {codon!r} encodes {expected_aa!r} "
                f"but the file says {aa_given!r}"
            )
        if not numeric:
            raise ValueError(
                f"line {lineno}: no count/frequency column for {codon!r}"
            )
        ints = [t for t in numeric if float(t) == int(float(t))]
        count = (int(round(float(ints[-1]))) if ints
                 else int(round(float(numeric[-1]) * 1000)))
        if count < 0:
            raise ValueError(f"line {lineno}: negative count for {codon!r}")
        raw[codon] = (expected_aa, count)
    if not raw:
        raise ValueError(
            "no codon rows found — expected lines like 'GCT A 120' or "
            "'GCT 120' (codon then count)"
        )
    return raw


def _codon_name_parts(name: str) -> tuple[str, str]:
    """Return (genus, species) as lowercased tokens from an entry name.

    Genus = first whitespace-delimited token; species = second token (or "").
    Names like "E. coli K12" yield ("e.", "coli"); "Escherichia coli" yields
    ("escherichia", "coli"). No normalization between abbreviated and
    unabbreviated genera — users search what they see.
    """
    parts = (name or "").strip().split()
    genus   = parts[0].lower() if parts else ""
    species = parts[1].lower() if len(parts) > 1 else ""
    return genus, species


def _codon_search(query: str, entries: "list | None" = None) -> list[dict]:
    """Ranked search over taxid, genus, species, and full name.

    Rank 0: taxid exact match
    Rank 1: taxid prefix match
    Rank 2: genus prefix (first whitespace token of name)
    Rank 3: species prefix (second whitespace token)
    Rank 4: substring anywhere in the full name

    Results are sorted by (rank, name) so same-genus entries cluster and
    the strongest match wins. An empty/whitespace query returns the
    registry naturally sorted by display name (`Escherichia coli K12`
    before `Escherichia coli K-12 MG1655`) so the unfiltered table
    reads in human-friendly order rather than disk-insertion order.
    Same-rank ties under a non-empty query also use the natural-sort
    secondary key (e.g. `E. coli K12` before `K-12 MG1655`).
    """
    if entries is None:
        entries = _codon_tables_load()
    q = (query or "").strip().lower()
    if not q:
        # Empty query → natural-sort the registry by display name so
        # `Escherichia coli K12` lands near the top in stable order
        # regardless of the JSON-file insertion order.
        return sorted(
            entries,
            key=lambda e: _natural_sort_key(str(e.get("name") or "")),
        )
    ranked: list[tuple[int, tuple, dict]] = []
    for e in entries:
        name_lc  = str(e.get("name", "")).lower()
        taxid_lc = str(e.get("taxid", "")).lower()
        genus, species = _codon_name_parts(e.get("name", ""))
        if taxid_lc and taxid_lc == q:
            rank = 0
        elif taxid_lc and taxid_lc.startswith(q):
            rank = 1
        elif genus and genus.startswith(q):
            rank = 2
        elif species and species.startswith(q):
            rank = 3
        elif q in name_lc:
            rank = 4
        else:
            continue
        # Secondary key uses natural sort so same-rank matches come
        # back in human-friendly order (`E. coli K12` before `K-12 MG1655`).
        ranked.append((rank, _natural_sort_key(name_lc), e))
    ranked.sort(key=lambda t: (t[0], t[1]))
    return [t[2] for t in ranked]


def _codon_parse_kazusa_html(html: str) -> "dict | None":
    """Parse Kazusa showcodon.cgi GCG-format HTML. Returns {codon: (aa, count)}
    or None on failure."""
    pre = re.search(r"<[Pp][Rr][Ee]>(.*?)</[Pp][Rr][Ee]>", html, re.DOTALL)
    text = pre.group(1) if pre else html
    pat = re.compile(r"\b([ACGTU]{3})\b\s+(\d+(?:\.\d+)?)", re.IGNORECASE)
    raw: dict = {}
    for m in pat.finditer(text):
        rna = m.group(1).upper()
        dna = rna.replace("U", "T")
        if dna not in _CODON_GENETIC_CODE or dna in raw:
            continue
        try:
            count = round(float(m.group(2)))
        except ValueError:
            continue
        raw[dna] = (_CODON_GENETIC_CODE[dna], count)
    # 2026-05-27 (audit-5 domesticator M1): require all 64 codons.
    # Pre-fix the threshold was 60, silently accepting up to 4
    # missing codons; if a rare codon (e.g. ATA-Ile) was missing
    # for an organism, `_codon_optimize` raised `ValueError("No
    # codons for amino acid …")` only when the protein happened to
    # contain that AA — surface unpredictably at design time. Now
    # malformed tables are rejected upfront.
    if len([c for c in raw if raw[c][0] != "?"]) < 64:
        return None
    return raw


def _safe_xml_parse(xml_data: str, *, allow_dtd: bool = False):
    """Parse XML with defense against billion-laughs / XXE tricks.

    Python's stdlib ET (expat) already refuses to fetch external entities
    since 3.7.1, so the remaining attack surface is DTD-declared entity
    expansion. Pre-fix we substring-matched `<!doctype` / `<!entity` only
    in the FIRST 4096 chars — exploitable with a long whitespace /
    comment prefix that pushes the DOCTYPE past the window.

    Replaced with a streaming prologue scan: skip leading whitespace +
    comments + processing instructions and inspect the first non-trivial
    declaration. If it's a DOCTYPE / ENTITY, refuse before handing to
    expat. NCBI / Kazusa / .dna history XML have no legitimate DTD, so
    this never false-positives.

    ``allow_dtd=True`` opts a caller into permitting an **external** DTD
    reference — e.g. NCBI BLAST's ``FORMAT_TYPE=XML`` output, which opens
    with ``<!DOCTYPE BlastOutput PUBLIC ... NCBI_BlastOutput.dtd>``. A
    standalone ``<!ENTITY>`` and any DOCTYPE carrying an internal subset
    (``[ … ]`` — where billion-laughs entity definitions live) are still
    refused. expat never fetches the external DTD (no network since
    3.7.1) and there are no entities to expand, so this stays XXE-safe.
    Default ``False`` keeps every existing caller's strict behaviour.
    """
    import io
    import xml.etree.ElementTree as ET
    # Streaming prologue scan: advance past whitespace, comments, and
    # processing instructions to find the first non-trivial declaration.
    i = 0
    n = len(xml_data)
    while i < n:
        c = xml_data[i]
        if c in " \t\r\n":
            i += 1
            continue
        # Comment: <!-- ... -->
        if xml_data.startswith("<!--", i):
            end = xml_data.find("-->", i + 4)
            if end == -1:
                # Unterminated comment — defer to expat for the parse
                # error so the user sees the proper diagnostic.
                break
            i = end + 3
            continue
        # Processing instruction: <?xml version="1.0"?> etc.
        if xml_data.startswith("<?", i):
            end = xml_data.find("?>", i + 2)
            if end == -1:
                break
            i = end + 2
            continue
        # DOCTYPE / ENTITY declaration — refuse (or, with allow_dtd, permit
        # only an external-DTD reference). Case-insensitive check on the
        # next ~16 chars (case-folding the WHOLE document is expensive on
        # multi-MB inputs).
        head = xml_data[i:i + 16].lower()
        if head.startswith("<!entity"):
            raise ET.ParseError(
                "XML contains a standalone ENTITY declaration — refusing"
            )
        if head.startswith("<!doctype"):
            if not allow_dtd:
                raise ET.ParseError(
                    "XML contains DTD/ENTITY — refusing to parse"
                )
            # Permit an external-DTD reference but refuse any internal
            # subset (`[ … ]`), which is where entity-expansion attacks
            # live. The DOCTYPE without a subset ends at the first `>`.
            close = xml_data.find(">", i)
            bracket = xml_data.find("[", i)
            if close == -1:
                break  # malformed — let expat surface the parse error
            if bracket != -1 and bracket < close:
                raise ET.ParseError(
                    "XML DOCTYPE has an internal subset — refusing to parse"
                )
            i = close + 1
            continue
        # Reached a normal start tag — safe to hand off to expat.
        break
    # 2026-05-27 (audit-3 M6): cap nesting depth via iterparse so a
    # 10k-deep `<Node><Node>...</Node></Node>` chain can't blow the
    # Python stack in downstream consumers (HistoryTree walkers,
    # qualifier readers). 256 levels is more than any legitimate
    # plasmid annotation tree ever produces.
    _MAX_DEPTH = 256
    depth = 0
    max_depth_seen = 0
    for event, _elem in ET.iterparse(
            io.StringIO(xml_data), events=("start", "end"),
    ):
        if event == "start":
            depth += 1
            if depth > max_depth_seen:
                max_depth_seen = depth
                if depth > _MAX_DEPTH:
                    raise ET.ParseError(
                        f"XML nesting exceeds {_MAX_DEPTH} levels "
                        f"(unbounded recursion guard)"
                    )
        elif event == "end":
            depth -= 1
    return ET.fromstring(xml_data)


def _ncbi_prep_term(query: str) -> str:
    """Turn a user query into an NCBI Entrez term.

    * Single token (typed-as-genus): combine an exact-taxon subtree search
      restricted to species rank with a wildcard prefix search via OR, so
      typing 'Escherichia' returns every Escherichia species (subtree hit)
      AND typing a partial like 'Escher' still matches via the wildcard.
    * Multi-word query: append '*' to the trailing token so 'Homo sapien'
      matches 'Homo sapiens' etc.
    * User-supplied wildcards or field tags pass through untouched.
    """
    q = (query or "").strip()
    if not q or "*" in q or "[" in q:
        return q
    tokens = q.split()
    if len(tokens) == 1:
        t = tokens[0]
        return f"({t}[Subtree] AND species[Rank]) OR {t}*"
    tokens[-1] = tokens[-1] + "*"
    return " ".join(tokens)


def _ncbi_taxid_search_terms(query: str) -> list[str]:
    """Cascading NCBI-taxonomy search terms, strictest first — mirrors the
    sister project ScriptoScope's `genbank_search` strategy (see
    `[SISTER]` in docs/invariants.md). The caller tries each term in
    order and stops at the first that returns hits, so an imprecise or
    partial species name still surfaces *related* taxa instead of a
    dead-end "no results".

    * Strategy 1 is `_ncbi_prep_term` — the precise-ish query (genus
      subtree + prefix wildcard for a single token; trailing wildcard
      for a multi-word name). The overwhelming majority of real queries
      resolve here, so this is identical to the pre-cascade behaviour.
    * For a MULTI-word query that comes back empty, two broader rounds
      kick in: every token prefix-wildcarded and AND-joined (tolerates a
      partial genus AS WELL AS a partial species — "Sacchar cerev"),
      then OR-joined (ANY token matches, so a stray or mistyped word
      still finds relatives — e.g. a genus typo "Homon sapiens" is
      rescued by the species epithet).

    A single-token query gets only strategy 1: its broader forms are
    already subsumed by the `OR {t}*` clause `_ncbi_prep_term` emits, so
    re-querying would just repeat the same search. A query the user has
    already steered with a `*` wildcard or a `[Field]` tag passes through
    verbatim — never second-guess an explicit Entrez query.
    """
    q = (query or "").strip()
    if not q:
        return []
    first = _ncbi_prep_term(q)
    if "*" in q or "[" in q:
        return [first]
    tokens = q.split()
    if len(tokens) < 2:
        return [first]
    terms = [first]
    for broadened in (
        " AND ".join(f"{tok}*" for tok in tokens),
        " OR ".join(f"{tok}*" for tok in tokens),
    ):
        if broadened not in terms:
            terms.append(broadened)
    return terms


# Response-size caps for upstream fetches: defends against a compromised /
# misconfigured / man-in-the-middled upstream that streams gigabytes at us.
# NCBI esearch / esummary XML for a 200-id batch is ~50 KB in practice;
# 4 MB is wildly generous. Kazusa showcodon HTML is ~30 KB; 1 MB is plenty.
_NCBI_MAX_RESPONSE_BYTES   = 4 * 1024 * 1024
_KAZUSA_MAX_RESPONSE_BYTES = 1 * 1024 * 1024


def _ncbi_taxid_search(query: str, retmax: int = 200,
                      timeout: float = 15.0) -> tuple:
    """Search NCBI taxonomy for candidates matching `query`. Returns
    (hits, total_count, status_message) where each hit is
    {'taxid': str, 'name': str}. Names come from a batched esummary call
    (one round-trip for up to `retmax` ids).

    Imprecise / partial queries are handled by a cascading search
    (`_ncbi_taxid_search_terms`, mirroring ScriptoScope's `genbank_search`):
    a strict query is tried first, and if it comes back EMPTY the search
    is automatically broadened — every token prefix-wildcarded, then
    OR-joined — so a related-but-not-exact species name still surfaces
    candidates. A network / parse / oversize failure aborts the cascade
    immediately (an empty result, by contrast, just falls through to the
    next, broader strategy). Pure network — run from a worker."""
    import urllib.parse
    import urllib.request
    import urllib.error as _urllib_error   # sweep #25 — narrow excepts
    import xml.etree.ElementTree as ET
    q = (query or "").strip()
    if not q:
        return [], 0, "Empty query"
    base = "https://eutils.ncbi.nlm.nih.gov/entrez/eutils"
    ids: list[str] = []
    total = 0
    broadened = False
    for idx, term in enumerate(_ncbi_taxid_search_terms(q)):
        params = urllib.parse.urlencode({
            "db": "taxonomy", "term": term,
            "retmax": str(retmax), "retmode": "xml",
        })
        try:
            req = urllib.request.Request(
                f"{base}/esearch.fcgi?{params}",
                headers={"User-Agent": "SpliceCraft/1.0"})
            with urllib.request.urlopen(req, timeout=timeout) as r:
                raw = r.read(_NCBI_MAX_RESPONSE_BYTES + 1)
            if len(raw) > _NCBI_MAX_RESPONSE_BYTES:
                _log.warning("NCBI esearch response exceeded %d bytes; truncating",
                              _NCBI_MAX_RESPONSE_BYTES)
                return [], 0, "NCBI returned an oversized response"
            xml_data = raw.decode("utf-8", errors="replace")
        except (OSError, _urllib_error.URLError) as exc:
            # Sweep #25 (2026-05-23): narrowed from bare `Exception` —
            # network failures land as `URLError` (timeout, DNS, refused)
            # or `OSError` (socket-level). Other exceptions (KeyError,
            # AttributeError) here would be real bugs and should
            # propagate to surface in the log + dialog. A network error
            # aborts the cascade (matches ScriptoScope's `?` propagation)
            # rather than masking an outage behind broader retries.
            _log.exception("NCBI esearch failed for %r", q)
            return [], 0, f"Network error: {exc}"
        try:
            # allow_dtd=True: NCBI eutils responses open with an EXTERNAL
            # DTD reference — `<!DOCTYPE eSearchResult PUBLIC "-//NLM//DTD
            # esearch 20060628//EN" ".../esearch.dtd">` — which has no
            # internal subset, so it stays XXE / billion-laughs safe (expat
            # never fetches the external DTD since Py 3.7.1, and there are no
            # entities to expand). Without this flag the strict parse rejects
            # EVERY real NCBI response with "XML contains DTD/ENTITY —
            # refusing to parse", which surfaced as the taxon-search "XML
            # parser error". Mirrors the BLAST-XML caller. See [PIT-19].
            root = _safe_xml_parse(xml_data, allow_dtd=True)
        except ET.ParseError as exc:
            return [], 0, f"Could not parse NCBI response: {exc}"
        cur_ids = [e.text for e in root.findall(".//Id") if e.text]
        if cur_ids:
            ids = cur_ids
            count_elem = root.find(".//Count")
            try:
                total = (int(count_elem.text)
                         if count_elem is not None and count_elem.text
                         else len(ids))
            except ValueError:
                total = len(ids)
            broadened = idx > 0
            break
    if not ids:
        return [], 0, f"No NCBI taxonomy entry for '{q}'"
    # Batched esummary: one round-trip for all retrieved ids
    names_by_id: dict[str, str] = {}
    try:
        sparams = urllib.parse.urlencode({
            "db": "taxonomy", "id": ",".join(ids), "retmode": "xml",
        })
        req = urllib.request.Request(f"{base}/esummary.fcgi?{sparams}",
                                     headers={"User-Agent": "SpliceCraft/1.0"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            sraw = r.read(_NCBI_MAX_RESPONSE_BYTES + 1)
        if len(sraw) > _NCBI_MAX_RESPONSE_BYTES:
            _log.warning("NCBI esummary response exceeded %d bytes; ignoring",
                          _NCBI_MAX_RESPONSE_BYTES)
            sxml = ""
        else:
            sxml = sraw.decode("utf-8", errors="replace")
        # allow_dtd=True — esummary carries the same external-DTD DOCTYPE
        # as esearch (`<!DOCTYPE eSummaryResult PUBLIC ... esummary-v1.dtd>`);
        # see the esearch parse above for why this is safe.
        sroot = _safe_xml_parse(sxml, allow_dtd=True) if sxml else None
        for doc in (sroot.findall(".//DocSum") if sroot is not None else []):
            did_el = doc.find("Id")
            if did_el is None or not did_el.text:
                continue
            did = did_el.text
            for item in doc.findall("Item"):
                if item.get("Name") == "ScientificName" and item.text:
                    names_by_id[did] = item.text
                    break
    except (OSError, _urllib_error.URLError, ET.ParseError):
        # Sweep #25 (2026-05-23): narrowed from bare `Exception`.
        _log.exception("NCBI esummary failed for ids %s", ids[:3])
    hits = [{"taxid": tid,
             "name":  names_by_id.get(tid, f"(taxid {tid})")}
            for tid in ids]
    msg = f"{total} hit(s) for '{q}'"
    if total > len(hits):
        msg = f"Showing {len(hits)} of {total} hits for '{q}' (refine to narrow)"
    if broadened:
        # No exact match — surfaced related taxa via the broadened
        # cascade. Tell the user so a loose hit isn't mistaken for a
        # precise one.
        msg += " · broadened to related names"
    return hits, total, msg


def _codon_fetch_kazusa(taxid: str, timeout: float = 15.0) -> tuple:
    """Fetch codon usage from Kazusa for an NCBI taxid. Returns
    (raw_dict_or_None, status_message). Pure network call — callers should
    invoke from a worker thread."""
    import urllib.request
    import urllib.error as _urllib_error  # sweep #25 — narrow excepts
    taxid = str(taxid).strip()
    if not taxid.isdigit():
        return None, f"Invalid taxid '{taxid}' (must be numeric)"
    url = (f"https://www.kazusa.or.jp/codon/cgi-bin/showcodon.cgi"
           f"?species={taxid}&aa=1&style=GCG")
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw = r.read(_KAZUSA_MAX_RESPONSE_BYTES + 1)
        if len(raw) > _KAZUSA_MAX_RESPONSE_BYTES:
            _log.warning("Kazusa response exceeded %d bytes; aborting",
                          _KAZUSA_MAX_RESPONSE_BYTES)
            return None, "Kazusa returned an oversized response"
        html = raw.decode("utf-8", errors="replace")
    except (OSError, _urllib_error.URLError) as exc:
        # Sweep #25 (2026-05-23): narrowed from bare `Exception`.
        _log.exception("Kazusa fetch failed for taxid %s", taxid)
        return None, f"Network error: {exc}"
    low = html.lower()
    if "not found" in low or "no data" in low:
        return None, f"Taxid {taxid} not found in Kazusa database"
    raw = _codon_parse_kazusa_html(html)
    if raw is None:
        return None, f"Could not parse Kazusa table for taxid {taxid}"
    return raw, f"Fetched from Kazusa: {len(raw)} codons (taxid {taxid})"


def _codon_build_aa_map(raw: dict) -> tuple[dict, dict]:
    """Given {codon: (aa, count)}, return (aa_codons, codon_frac) where
    aa_codons[aa] = [(codon, frac), ...] sorted by fraction descending, and
    codon_frac[codon] = fractional usage for its amino acid."""
    from collections import defaultdict
    aa_total: dict = defaultdict(int)
    for codon, (aa, count) in raw.items():
        aa_total[aa] += int(count)
    codon_frac: dict = {}
    for codon, (aa, count) in raw.items():
        total = aa_total.get(aa, 0) or 1
        codon_frac[codon] = count / total
    aa_codons: dict = defaultdict(list)
    for codon, (aa, count) in raw.items():
        if aa == "*":
            continue
        aa_codons[aa].append((codon, codon_frac[codon]))
    for aa in aa_codons:
        aa_codons[aa].sort(key=lambda x: -x[1])
    return dict(aa_codons), codon_frac


def _codon_allocate(codons: list, n: int) -> list:
    """Pick ``n`` codons from ``[(codon, frac), ...]`` so the chosen multiset
    matches the frequency distribution as closely as possible (largest-
    remainder apportionment), then interleave them so no single codon
    clusters at the front. Deterministic: equal remainders break by input
    order, so the same ``(codons, n)`` always yields the same list.

    Shared by amino-acid positions AND frequency-matched stop codons. The
    return is GUARANTEED to be exactly length ``n`` (empty when ``n <= 0``):
    for a normalized table the apportionment already sums to ``n``, but a
    hand-rolled / truncated table whose fractions don't sum to 1 is padded
    with (or truncated to) the most-frequent codon so the caller can never
    receive a short list that would leave a position unfilled — i.e. NO
    rogue/empty codon ever reaches the output. Every codon in ``codons`` is
    synonymous (same residue, or all stops), so padding never changes the
    encoded amino acid."""
    if n <= 0:
        return []
    if len(codons) == 1:
        return [codons[0][0]] * n
    targets: list = []
    remainders: list = []
    allocated = 0
    for codon, frac in codons:
        exact = n * frac
        floored = int(exact)
        targets.append(floored)
        remainders.append((exact - floored, len(targets) - 1))
        allocated += floored
    shortage = n - allocated
    remainders.sort(key=lambda x: -x[0])
    for k in range(max(0, shortage)):
        # `% len` guards a malformed table whose rounding leaves a shortage
        # larger than the codon count; for a normalized table
        # shortage <= len(remainders), so this is a plain index.
        targets[remainders[k % len(remainders)][1]] += 1
    queues = [[codon] * cnt
              for (codon, _frac), cnt in zip(codons, targets) if cnt > 0]
    interleaved: list = []
    i = 0
    while any(queues):
        q = queues[i % len(queues)]
        if q:
            interleaved.append(q.pop(0))
        i += 1
    # Length guarantee (defensive — a no-op for any table whose per-AA
    # fractions sum to 1): pad short with the most-frequent synonym,
    # truncate long.
    if len(interleaved) < n:
        interleaved += [codons[0][0]] * (n - len(interleaved))
    return interleaved[:n]


def _codon_optimize(protein: str, raw: dict, *, stops: int = 1) -> str:
    """Frequency-matching codon optimization: distribute synonymous codons
    across the protein so each amino acid's codon distribution matches
    the target organism's overall usage frequencies. Raises ValueError on
    unknown amino acids.

    Stop codons (2026-05-30): a run of trailing ``*`` in ``protein`` is
    honored verbatim — ``"MGK*"`` → one stop, ``"MGK**"`` → two, ``"MGK***"``
    → three — and ``stops`` is then ignored. A ``*`` anywhere but that
    trailing run raises ValueError (a premature stop is never silently
    encoded). When the protein carries no trailing ``*``, ``stops`` (default
    1, negatives clamped to 0) stop codons are appended. A SINGLE stop is
    always ``TAA`` (the strongest terminator / lowest readthrough in E. coli,
    and the historical default that downstream site-scrubbing assumes); 2+
    stops are frequency-matched to the table's OWN stop-codon usage so the
    emitted run resists readthrough with organism-appropriate diversity,
    falling back to ``TAA`` only when the table declares no stop codons.

    The amino-acid body is apportioned by `_codon_allocate`, which excludes
    stop codons from every residue's synonym pool — so a body position can
    NEVER be a stop (no premature internal stop) and is always a real codon
    (no rogue/empty base). Output length is exactly ``3*len(body) +
    3*n_stops``.

    Distinct from Angov-style codon HARMONIZATION (Angov 2011), which
    requires a SOURCE organism's codon usage to preserve relative
    rare-codon positions in the target (those positions encode
    translation pauses important for cotranslational folding). We only
    consume the target table, so this is pure optimization, not
    harmonization. Renamed 2026-05-01 to stop misleading users."""
    aa_codons, codon_frac = _codon_build_aa_map(raw)
    # Peel a trailing run of stop requests; a '*' anywhere else is an error.
    body = protein
    n_trailing = 0
    while body and body[-1] == "*":
        body = body[:-1]
        n_trailing += 1
    if "*" in body:
        raise ValueError(
            "stop codon '*' is only allowed at the end of the protein")
    n_stops = n_trailing if n_trailing else max(0, int(stops))

    aa_positions: dict = {}
    for i, aa in enumerate(body):
        aa_positions.setdefault(aa.upper(), []).append(i)
    codon_at = [""] * len(body)
    for aa, positions in aa_positions.items():
        codons_for_aa = aa_codons.get(aa, [])
        if not codons_for_aa:
            raise ValueError(f"No codons for amino acid '{aa}' in this table")
        for pos, codon in zip(positions,
                              _codon_allocate(codons_for_aa, len(positions))):
            codon_at[pos] = codon

    if n_stops <= 1:
        tail = "TAA" * n_stops
    else:
        stop_codons = sorted(
            ((c, codon_frac[c]) for c, (a, _ct) in raw.items() if a == "*"),
            key=lambda x: -x[1])
        tail = "".join(_codon_allocate(stop_codons or [("TAA", 1.0)], n_stops))
    return "".join(codon_at) + tail


def _forbidden_hit_set(seq: str, patterns) -> set[tuple[str, int]]:
    """Return ``{(pattern, position)}`` for every occurrence of every
    pattern in *seq*.

    IUPAC-aware (2026-05-30 hardening): a degenerate recognition site
    (``GGWCC``, ``CCANNNNNNTGG``, ``RGATCY`` …) is matched against concrete
    A/C/G/T via `_iupac_pattern`, not as a literal substring — so forbidding
    a degenerate-site enzyme actually finds (and the caller removes) its real
    sites instead of silently matching nothing. For an exact A/C/G/T site
    this is identical to the previous `seq.find` scan. Overlapping
    occurrences are reported via a zero-width lookahead (codon swaps are 3→3
    bases, so positions stay stable, letting the caller compare before/after
    hit sets directly). A pattern that isn't valid IUPAC is skipped."""
    out: set[tuple[str, int]] = set()
    for p in patterns:
        try:
            pat = _iupac_pattern(p)
        except ValueError:
            continue
        for m in re.finditer(f"(?={pat.pattern})", seq):
            out.add((p, m.start()))
    return out


def _codon_fix_sites(dna: str, protein: str, raw: dict,
                     sites: "dict | None" = None,
                     *, has_appended_stop: bool = True) -> tuple:
    """Substitute synonymous codons to remove internal restriction sites.

    ``sites`` is a forward-strand ``{name: site}`` dict; reverse complements
    are added automatically for non-palindromic sites. Returns
    ``(new_dna, fixes)``.

    ``has_appended_stop`` (2026-05-27 audit-5 H2): set to True when ``dna``
    ends in a SYNTHETIC stop codon that the caller appended (e.g.
    ``_codon_optimize`` always appends TAA). The boundary check then
    skips the last codon to avoid silently substituting an appended
    stop. Set to False when the caller passes a raw CDS region without
    an appended stop — without this kwarg pre-2026-05-27 the last 1-2
    codons were silently skipped for any forbidden site overlapping
    them, and the caller's "remaining sites" check then aborted with
    "no synonymous alternative" when the code had actually refused to
    try the swap.

    Hardening (2026-04-21) — a candidate swap is accepted only if it:
      1. Actually removes the target site at the current position, AND
      2. Introduces **no new** forbidden site (forward or RC) anywhere
         in the full sequence — counted against the full input site set,
         not just the enzyme currently being iterated. This guards
         against the classic failure mode of fixing BsaI by accidentally
         spawning an Esp3I (or the RC of either) a few bases away.

    Multiple occurrences of the same site are processed left-to-right;
    each swap only needs to remove its own position, so repeated sites
    of the same enzyme are handled correctly (pre-2026-04-21 the check
    was ``site not in test`` which failed when two copies were present).
    """
    if sites is None:
        sites = _CODON_DEFAULT_FORBIDDEN
    expanded: dict = {}
    for name, site in sites.items():
        site = str(site or "").upper()
        if not site:
            continue
        # Validate as an IUPAC recognition site; skip (rather than crash the
        # whole optimize) an enzyme whose site carries a stray non-IUPAC char.
        try:
            _iupac_pattern(site)
        except ValueError:
            _log.warning("Codon site-scrub: skipping %r (%s) — not a valid "
                          "IUPAC recognition site", site, name)
            continue
        expanded[name] = site
        rc = _mut_revcomp(site)
        if rc != site:
            expanded[f"{name}_rc"] = rc
    # Flat tuple of every forbidden pattern (forward + RC). Used by the
    # per-swap cross-check to veto swaps that would introduce a NEW
    # pattern anywhere (different enzyme, different strand, different
    # position — the check is global).
    all_forbidden = tuple(expanded.values())
    # Precompiled (cached) IUPAC matchers for the per-enzyme outer scan, so
    # a degenerate site is actually located (not literal-substring searched).
    site_pats = {nm: _iupac_pattern(st) for nm, st in expanded.items()}
    aa_codons, _ = _codon_build_aa_map(raw)
    dna_list = list(dna)
    fixes: list[str] = []
    for enzyme, site in expanded.items():
        pat = site_pats[enzyme]
        pos = 0
        while True:
            seq = "".join(dna_list)
            m = pat.search(seq, pos)
            if m is None:
                break
            idx = m.start()
            fixed = False
            lo_codon = max(0, (idx // 3) - 1)
            hi_codon = (idx + len(site)) // 3 + 2
            before_hits = _forbidden_hit_set(seq, all_forbidden)
            for codon_idx in range(lo_codon, hi_codon):
                codon_start = codon_idx * 3
                # 2026-05-27 (audit-5 H2): the `- 3` skip is only
                # valid when the caller appended a synthetic stop
                # codon to `dna_list`. Raw CDS regions (passed by
                # `_design_gb_primers`) don't end in an appended stop,
                # and skipping their last codon silently leaves a
                # forbidden site overlapping the C-terminus unfixed.
                last_safe = (
                    len(dna_list) - 3 if has_appended_stop
                    else len(dna_list)
                )
                if codon_start + 3 > last_safe:
                    break
                if codon_idx >= len(protein):
                    break
                aa = protein[codon_idx].upper()
                current = "".join(dna_list[codon_start:codon_start + 3])
                for alt, frac in aa_codons.get(aa, []):
                    if alt == current:
                        continue
                    test = dna_list[:]
                    test[codon_start:codon_start + 3] = list(alt)
                    test_seq = "".join(test)
                    after_hits = _forbidden_hit_set(test_seq, all_forbidden)
                    # (1) Target site at idx must be gone.
                    if (site, idx) in after_hits:
                        continue
                    # (2) No new forbidden hit appears anywhere.
                    #     (Existing hits elsewhere are fine — later
                    #     iterations of this loop will process them.)
                    if after_hits - before_hits:
                        continue
                    dna_list = test
                    strand = " (rc)" if enzyme.endswith("_rc") else ""
                    fixes.append(
                        f"{enzyme.replace('_rc', '')}{strand} at nt {idx+1}: "
                        f"{current}→{alt} (codon {codon_idx+1} {aa}, "
                        f"freq={frac:.3f})"
                    )
                    fixed = True
                    break
                if fixed:
                    break
            if not fixed:
                pos = idx + 1
    return "".join(dna_list), fixes


# ── Scrub: clone-free restriction-site removal (improved QuikChange) ────────
#
# "Scrub" cures a plasmid of chosen restriction recognition sites by
# introducing the MINIMAL set of point substitutions that destroy each
# site WITHOUT (a) changing any overlapping CDS's protein (synonymous /
# silent), (b) creating a NEW copy of any forbidden site anywhere, or
# (c) — softly — touching annotated non-coding elements when avoidable.
# The result is a single contiguous circular sequence the user makes in
# the lab by improved-QuikChange whole-plasmid PCR + self-recircularization
# (DpnI, transform — no ligase, no fragment assembly). See docs/invariants
# [INV-97] and the MutagenizeModal "Scrub" tab.
#
# Why it leans on the hardened primitives instead of rolling its own:
#   * Site enumeration AND the final "did I introduce a new site?" guard go
#     through `_scan_restriction_sites(circular=True)`, so origin-spanning
#     sites (sacred inv #6) and reverse-strand coords (sacred inv #2) are
#     handled by code that already has tests.
#   * Synonymy is verified by RE-TRANSLATING every overlapping CDS with
#     `_translate_cds` (the canonical translator) rather than hand-mapping
#     codons — wrap, reverse strand, /codon_start and /transl_table all come
#     out right for free, including a site straddling TWO CDSes on opposite
#     strands (both frames must stay synonymous or the change is rejected).
#   * Every cure is a 1-base→1-base SUBSTITUTION, so the cured sequence is
#     the SAME LENGTH and feature coordinates never shift — the caller can
#     swap `record.seq` and keep features verbatim (no `_rebuild_record_
#     with_edit`, no coordinate migration).

# Marquee use case is clone-free MoClo / Golden Braid domestication, so the
# default target set is the Type IIS cutters assembly can't tolerate inside a
# part. Esp3I covers its isoschizomer BsmBI (same CGTCTC site).
_SCRUB_DEFAULT_ENZYMES: "tuple[str, ...]" = ("BsaI", "Esp3I", "BbsI")
# Edits within this many bp share a single QuikChange primer pair (one PCR
# round); edits farther apart need separate sequential rounds.
_SCRUB_PRIMER_FOOTPRINT = 30
# Cap on substitutions tried to kill one site. A 6-cutter almost always dies
# to a single change; 3 covers a constrained CDS where the obvious wobble
# base isn't free. Beyond this we report the site as un-scrubbable rather
# than mangling a long stretch.
_SCRUB_MAX_CHANGES = 3


def _circ_window(seq: str, start: int, length: int, n: int) -> str:
    """Return `length` bases of `seq` starting at forward coord `start`,
    wrapping the origin when `start + length > n` (`n == len(seq)`)."""
    end = start + length
    if end <= n:
        return seq[start:end]
    return seq[start:] + seq[:end - n]


def _scrub_pos_in_feat(g: int, s: int, e: int) -> bool:
    """Wrap-aware membership: is genome coord `g` inside span `[s, e)`
    (where `e < s` signals an origin wrap)? Module-level mirror of
    `PlasmidMap._bp_in` for the Scrub path."""
    if e >= s:
        return s <= g < e
    return g >= s or g < e


def _scrub_is_transition(a: str, b: str) -> bool:
    """A↔G / C↔T are transitions; the other four swaps are transversions.
    Used only as a tie-break — transitions are the milder substitution."""
    return {a, b} in ({"A", "G"}, {"C", "T"})


def _scrub_resolve_sites(enzymes) -> "dict[str, str]":
    """Resolve enzyme names → forward recognition sites from the merged
    built-in + custom catalog. Unknown names and non-IUPAC sites are
    skipped (one bad custom enzyme never aborts the whole scrub)."""
    enz = _all_enzymes()
    out: "dict[str, str]" = {}
    for nm in enzymes or ():
        info = enz.get(str(nm))
        if not info:
            continue
        site = str(info[0] or "").upper()
        if not site:
            continue
        try:
            _iupac_pattern(site)
        except ValueError:
            continue
        out[str(nm)] = site
    return out


def _scrub_expand_forbidden(forward: "dict[str, str]") -> "tuple[str, ...]":
    """Forward sites + their reverse complements (deduped) as the flat
    tuple `_forbidden_hit_set` consumes — so the 'no new site' guard vetoes
    a swap that would spawn a forbidden site on EITHER strand."""
    out: "list[str]" = []
    for site in forward.values():
        if site not in out:
            out.append(site)
        rc = _rc(site)
        if rc not in out:
            out.append(rc)
    return tuple(out)


def _scrub_scan_targets(seq: str, allowed: "frozenset[str]",
                        circular: bool) -> "list[dict]":
    """One entry per recognition-site INSTANCE of the allowed enzymes:
    `{enzyme, strand, rec_start, rec_end, positions}` where `positions` is
    the wrap-aware list of genome coords the recognition covers. Counts
    only LABELED resite pieces (sacred inv #6 — a wrap hit's unlabeled
    head piece is a continuation, not a second site)."""
    n = len(seq)
    hits = _scan_restriction_sites(
        seq, min_recognition_len=1, unique_only=False,
        circular=circular, allowed_enzymes=allowed)
    out: "list[dict]" = []
    for h in hits:
        if h.get("type") != "resite" or not h.get("label"):
            continue
        rs = h.get("rec_start", h["start"])
        re_ = h.get("rec_end", h["end"])
        if re_ < rs:                      # origin wrap
            positions = list(range(rs, n)) + list(range(0, re_))
        else:
            positions = list(range(rs, re_))
        if not positions:
            continue
        out.append({
            "enzyme": h["label"], "strand": h.get("strand", 1),
            "rec_start": rs, "rec_end": re_, "positions": positions,
        })
    out.sort(key=lambda t: (t["rec_start"], t["enzyme"], t["strand"]))
    return out


def _scrub_overlapping_feats(target: dict, feats: list) -> tuple:
    """Split `feats` into (cds_feats, other_feats) that overlap the target
    recognition window. Only 'CDS' constrains synonymy; everything else
    (gene/promoter/RBS/rep_origin/…) is 'annotated non-coding' and only
    earns a soft penalty for being touched."""
    posset = set(target["positions"])
    cds: list = []
    other: list = []
    for f in feats:
        s = f.get("start")
        e = f.get("end")
        if s is None or e is None:
            continue
        if not any(_scrub_pos_in_feat(g, s, e) for g in posset):
            continue
        if f.get("type") == "CDS":
            cds.append(f)
        else:
            other.append(f)
    return cds, other


def _scrub_region_label(cds_feats: list, other_feats: list) -> str:
    """Human label for where a site sits, for the preview table."""
    if cds_feats:
        names = ", ".join(str(f.get("label") or "CDS") for f in cds_feats)
        return f"CDS: {names}"
    if other_feats:
        names = ", ".join(str(f.get("label") or f.get("type") or "?")
                          for f in other_feats)
        return f"non-coding (in {names})"
    return "non-coding"


def _scrub_cds_protein(seq: str, f: dict) -> str:
    """Translate one CDS feature dict on `seq` via the canonical translator,
    honouring wrap / strand / _exons / codon_start / transl_table."""
    return _translate_cds(
        seq,
        f.get("_orig_start", f["start"]),
        f.get("_orig_end", f["end"]),
        f.get("strand", 1),
        f.get("_exons"),
        int(f.get("codon_start", 1) or 1),
        int(f.get("transl_table", 1) or 1),
    )


def _scrub_introduces_site(orig: str, test: str, target: dict,
                           all_forbidden: "tuple[str, ...]", n: int) -> bool:
    """True if `test` has a forbidden site near the edit that `orig` didn't.

    A substitution can only create a new site within (L-1) bp of a changed
    base (L = longest forbidden site), so a padded circular window around
    the recognition covers every site this change could spawn — comparing
    before/after hit sets on that SAME window is wrap-safe (a site present
    at the window's own boundary in both is not 'new'). The caller's final
    full re-scan is the authoritative whole-plasmid guard; this is the fast
    per-candidate pre-filter so we PICK a clean candidate."""
    L = max((len(s) for s in all_forbidden), default=8)
    pad = max(L - 1, 1)
    win_len = len(target["positions"]) + 2 * pad
    if win_len >= n:                       # tiny plasmid — scan it all
        a = orig + orig[:L - 1]
        b = test + test[:L - 1]
    else:
        start = (target["rec_start"] - pad) % n
        a = _circ_window(orig, start, win_len, n)
        b = _circ_window(test, start, win_len, n)
    return bool(_forbidden_hit_set(b, all_forbidden)
                - _forbidden_hit_set(a, all_forbidden))


def _scrub_cds_reading_positions(f: dict, n: int) -> tuple:
    """Genome positions of a CDS feature in 5'→3' CODING order (after the
    ``/codon_start`` offset), plus its strand. Codon ``i`` is positions
    ``[3i:3i+3]``; on the reverse strand the coding base at each position is
    the complement of the top strand. Mirrors the slice logic in
    `_cds_aa_list` / `_translate_cds` so frequency look-ups land on exactly
    the codons the synonymy check translates."""
    s = f.get("_orig_start", f["start"])
    e = f.get("_orig_end", f["end"])
    strand = f.get("strand", 1)
    exons = f.get("_exons")
    cs = max(0, min(2, int(f.get("codon_start", 1) or 1) - 1))
    if exons:
        gpos: list = []
        for xs, xe in exons:
            gpos.extend(range(xs, xe))
    elif e < s:                              # origin wrap
        gpos = list(range(s, n)) + list(range(0, e))
    else:
        gpos = list(range(s, e))
    if strand == -1:
        gpos = gpos[::-1]
    return gpos[cs:], strand


def _scrub_one_site(seq: str, target: dict, feats: list,
                    forward: "dict[str, str]",
                    all_forbidden: "tuple[str, ...]", n: int, *,
                    codon_frac: "dict | None" = None,
                    max_changes: int = _SCRUB_MAX_CHANGES) -> tuple:
    """Find the minimal substitution set that destroys ONE site instance.

    Returns `(changes, region, None)` where `changes = {genome_pos:
    new_base}`, or `(None, region, reason)` when the site can't be cured
    silently. A candidate is accepted only if it (1) destroys this
    instance, (3) leaves every overlapping CDS's protein unchanged, and
    (2) introduces no new forbidden site near the edit. Among the accepted,
    the score prefers: fewest changes → not touching annotated bases →
    (when `codon_frac` is given) the host-frequent synonymous codon →
    transitions over transversions → GC-neutral → lexicographic
    (deterministic, so the same plasmid always cures the same way).

    `codon_frac` (``{codon: usage_fraction}``) is a TIE-BREAK ONLY: synonymy
    is already guaranteed by check (3), so even a wrong frame map could only
    pick a less-preferred — never a non-silent — cure."""
    from itertools import combinations, product
    positions = target["positions"]
    site_len = len(positions)
    cds_feats, other_feats = _scrub_overlapping_feats(target, feats)
    region = _scrub_region_label(cds_feats, other_feats)
    orig_aa = [_scrub_cds_protein(seq, f) for f in cds_feats]
    annotated: set = set()
    for f in other_feats:
        s = f.get("start")
        e = f.get("end")
        for g in positions:
            if _scrub_pos_in_feat(g, s, e):
                annotated.add(g)
    # Reading-frame maps for overlapping CDSes, so a coding cure can prefer
    # the host-frequent synonymous codon. Built once per site (not per
    # candidate). Skipped entirely when no codon table was supplied.
    cds_frames: list = []
    if codon_frac:
        for f in cds_feats:
            gpos, st = _scrub_cds_reading_positions(f, n)
            cds_frames.append((gpos, st, {g: j for j, g in enumerate(gpos)}))
    fwd_site = forward[target["enzyme"]]
    pat_f = _iupac_pattern(fwd_site)
    pat_r = _iupac_pattern(_rc(fwd_site))
    best: "tuple | None" = None
    for k in range(1, max_changes + 1):
        for combo in combinations(positions, k):
            # Each chosen position is forced to a DIFFERENT base, so every
            # candidate makes exactly `k` real changes (no silent no-ops).
            alts = [[b for b in "ACGT" if b != seq[g]] for g in combo]
            for repl in product(*alts):
                tl = list(seq)
                for j, g in enumerate(combo):
                    tl[g] = repl[j]
                test = "".join(tl)
                # (1) this instance must be gone (check the exact window,
                #     both strands so a reverse-strand hit is covered).
                win = _circ_window(test, target["rec_start"], site_len, n)
                if pat_f.fullmatch(win) or pat_r.fullmatch(win):
                    continue
                # (3) synonymous in every overlapping CDS frame.
                if any(_scrub_cds_protein(test, f) != orig_aa[i]
                       for i, f in enumerate(cds_feats)):
                    continue
                # (2) no NEW forbidden site near the edit.
                if _scrub_introduces_site(seq, test, target,
                                          all_forbidden, n):
                    continue
                # Codon-usage preference: total fraction of the resulting
                # codons at each changed coding position (higher = better).
                freq = 0.0
                for gpos, st, idx in cds_frames:
                    for g in combo:
                        jj = idx.get(g)
                        if jj is None:
                            continue
                        trip = gpos[(jj // 3) * 3:(jj // 3) * 3 + 3]
                        if len(trip) < 3:
                            continue
                        codon = ("".join(_rc(test[p]) for p in trip)
                                 if st == -1 else
                                 "".join(test[p] for p in trip))
                        freq += (codon_frac or {}).get(codon, 0.0)
                score = (
                    k,
                    sum(1 for g in combo if g in annotated),
                    -round(freq, 6),
                    sum(1 for j in range(k)
                        if not _scrub_is_transition(seq[combo[j]], repl[j])),
                    sum(1 for j in range(k)
                        if (seq[combo[j]] in "GC") != (repl[j] in "GC")),
                    repl,
                )
                if best is None or score < best[0]:
                    best = (score, {combo[j]: repl[j] for j in range(k)})
        if best is not None:        # found the minimal-k solution; stop
            break
    if best is None:
        return None, region, ("no silent substitution removes this site "
                              "without creating another")
    return best[1], region, None


def _scrub_cluster_edits(positions: list, n: int,
                         footprint: int = _SCRUB_PRIMER_FOOTPRINT) -> list:
    """Group edit positions into QuikChange rounds: consecutive positions
    within `footprint` bp share one primer pair. Merges the first and last
    clusters when they sit within `footprint` across the origin."""
    if not positions:
        return []
    ps = sorted(set(positions))
    clusters: "list[list[int]]" = [[ps[0]]]
    for p in ps[1:]:
        if p - clusters[-1][-1] <= footprint:
            clusters[-1].append(p)
        else:
            clusters.append([p])
    if len(clusters) > 1:
        # Distance from the last cluster's tail, across the origin, to the
        # first cluster's head.
        if (clusters[0][0] + n) - clusters[-1][-1] <= footprint:
            clusters[0] = clusters[-1] + clusters[0]
            clusters.pop()
    return clusters


def _scrub_design(seq: str, feats: "list | None" = None,
                  enzymes=None, *, circular: bool = True,
                  codon_raw: "dict | None" = None) -> dict:
    """Plan a clone-free scrub of `seq`. Returns a dict with the cured
    sequence, the per-base edits, which sites were removed vs skipped, the
    QuikChange round clustering, and any warnings. Pure biology — designs
    no primers (see `_scrub_qc_primers`) and mutates nothing on disk.

    `codon_raw` (an organism's ``{codon: (aa, count)}`` usage table) is an
    optional preference: when a coding site has more than one silent cure,
    the host-frequent synonymous codon wins. Omit it and ties fall back to
    the deterministic transition/GC/lexicographic order."""
    seq = (seq or "").upper()
    n = len(seq)
    forward = _scrub_resolve_sites(
        enzymes if enzymes is not None else _SCRUB_DEFAULT_ENZYMES)
    codon_frac: "dict | None" = None
    if codon_raw:
        try:
            _, codon_frac = _codon_build_aa_map(codon_raw)
        except Exception:
            codon_frac = None
    result: dict = {
        "ok": True, "orig_seq": seq, "cured_seq": seq,
        "enzymes": sorted(forward.keys()),
        "edits": [], "sites_removed": [], "sites_skipped": [],
        "clusters": [], "n_rounds": 0, "warnings": [],
    }
    if not seq:
        result["warnings"].append("No sequence loaded.")
        return result
    if not forward:
        result["warnings"].append("No valid enzymes selected to scrub.")
        return result
    allowed = frozenset(forward.keys())
    all_forbidden = _scrub_expand_forbidden(forward)
    feats = [f for f in (feats or [])
             if f.get("start") is not None and f.get("end") is not None]

    working = list(seq)
    failed: set = set()
    # Each successful cure removes >=1 target and (guard #2) adds none, so the
    # target count strictly drops; failed targets are parked. The cap is a
    # belt-and-braces backstop against a pathological cascade.
    initial = _scrub_scan_targets(seq, allowed, circular)
    max_iter = 2 * len(initial) + 8
    it = 0
    while it < max_iter:
        it += 1
        cur = "".join(working)
        targets = [t for t in _scrub_scan_targets(cur, allowed, circular)
                   if (t["enzyme"], t["rec_start"], t["strand"]) not in failed]
        if not targets:
            break
        t = targets[0]
        ident = (t["enzyme"], t["rec_start"], t["strand"])
        changes, region, reason = _scrub_one_site(
            cur, t, feats, forward, all_forbidden, n, codon_frac=codon_frac)
        if changes is None:
            result["sites_skipped"].append({
                "enzyme": t["enzyme"], "pos": t["rec_start"],
                "strand": t["strand"], "region": region, "reason": reason})
            failed.add(ident)
            continue
        for g, nb in sorted(changes.items()):
            result["edits"].append({
                "pos": g, "frm": cur[g], "to": nb,
                "region": region, "enzyme": t["enzyme"]})
            working[g] = nb
        result["sites_removed"].append({
            "enzyme": t["enzyme"], "pos": t["rec_start"],
            "strand": t["strand"], "region": region})

    cured = "".join(working)

    # Substitution-only invariant — should be impossible to violate, but a
    # length drift would corrupt every downstream feature coordinate, so
    # abort loudly rather than ship it.
    if len(cured) != n:
        _log.error("Scrub: length drift %d->%d — aborting cure", n, len(cured))
        return {**result, "ok": False, "cured_seq": seq, "edits": [],
                "sites_removed": [],
                "warnings": result["warnings"] + ["Internal error: aborted "
                "to protect sequence integrity."]}
    result["cured_seq"] = cured

    # Authoritative wrap-aware guard: by the loop's exit condition the only
    # residual selected-enzyme sites are the ones we explicitly parked as
    # failed. Anything else means a cure cascade re-formed or spawned a site
    # — never observed (guard #2 forbids it), but if it ever happens we must
    # NOT claim the plasmid is clean.
    for t in _scrub_scan_targets(cured, allowed, circular):
        ident = (t["enzyme"], t["rec_start"], t["strand"])
        if ident in failed:
            continue
        _log.error("Scrub: unexpected residual %s at %d after cure pass",
                   t["enzyme"], t["rec_start"])
        result["sites_removed"] = [
            r for r in result["sites_removed"]
            if (r["enzyme"], r["pos"], r["strand"]) != ident]
        result["sites_skipped"].append({
            "enzyme": t["enzyme"], "pos": t["rec_start"],
            "strand": t["strand"], "region": "?",
            "reason": "could not be removed without side effects"})

    clusters = _scrub_cluster_edits([e["pos"] for e in result["edits"]], n)
    result["clusters"] = [{"positions": c} for c in clusters]
    result["n_rounds"] = len(clusters)
    if n > 8000:
        result["warnings"].append(
            f"Plasmid is {n:,} bp — whole-plasmid QuikChange amplifies "
            "linearly and less efficiently above ~8 kb; use a long extension "
            "time (~1 min/kb) and more template.")
    return result


def _codon_forbidden_sites() -> "dict[str, str]":
    """Resolve the persisted ``codon_forbidden_enzymes`` name list into the
    ``{name: recognition_site}`` map that `_codon_fix_sites` consumes, drawing
    sites from the merged built-in + custom enzyme set. A name that's unknown
    (e.g. a custom enzyme since deleted) or whose site isn't valid IUPAC is
    skipped. An empty / missing list means 'scrub nothing'. Default ['BsaI'].
    """
    names = _get_setting("codon_forbidden_enzymes", ["BsaI"])
    if not isinstance(names, list):
        names = ["BsaI"]
    enz = _all_enzymes()
    out: dict[str, str] = {}
    for n in names:
        info = enz.get(str(n))
        if not info:
            continue
        site = str(info[0] or "").upper()
        if not site:
            continue
        try:
            _iupac_pattern(site)
        except ValueError:
            continue
        out[str(n)] = site
    return out


def _forbidden_sites_label() -> str:
    """Button label showing how many enzyme sites are currently forbidden."""
    names = _get_setting("codon_forbidden_enzymes", ["BsaI"])
    n = len(names) if isinstance(names, list) else 0
    return f"Avoid sites ({n})"


def _open_forbidden_sites_picker(screen, button_id: str) -> None:
    """Open `ForbiddenSitesModal` from `screen`, persist the chosen enzyme
    list to the shared `codon_forbidden_enzymes` setting, and relabel
    `button_id` with the new count. Shared by the Mutagenize + Synthesis
    'Avoid sites' buttons (both surfaces optimize against the same set)."""
    current = _get_setting("codon_forbidden_enzymes", ["BsaI"])
    if not isinstance(current, list):
        current = ["BsaI"]

    def _picked(names: "list | None") -> None:
        if names is None:
            return
        _set_setting("codon_forbidden_enzymes", [str(n) for n in names])
        try:
            screen.query_one(button_id, Button).label = _forbidden_sites_label()
        except NoMatches:
            pass

    screen.app.push_screen(ForbiddenSitesModal(list(current)), callback=_picked)


def _codon_cai(dna: str, raw: dict) -> float:
    """Codon Adaptation Index (geometric mean of per-codon freq ÷ peak freq
    of its amino-acid synonymy group). Skips stops and unknown codons."""
    import math
    aa_codons, codon_frac = _codon_build_aa_map(raw)
    w: list[float] = []
    for i in range(0, len(dna) - 2, 3):
        codon = dna[i:i + 3].upper()
        entry = raw.get(codon)
        if not entry or entry[0] == "*":
            continue
        peak = aa_codons[entry[0]][0][1] if entry[0] in aa_codons else 0.0
        if peak > 0:
            w.append(codon_frac.get(codon, 0.0) / peak)
    if not w:
        return 0.0
    return math.exp(sum(math.log(max(v, 1e-10)) for v in w) / len(w))


def _codon_gc(dna: str) -> float:
    """GC%. Empty string → 0."""
    if not dna:
        return 0.0
    gc = sum(1 for c in dna.upper() if c in "GC")
    return gc / len(dna) * 100.0


# Common cloning enzymes for the RE-site dropdown in the cloning primer panel.
