    @_action_log("app.edit.custom_enzyme_list")
    @_action_log("app.capture.to_features")
    def action_capture_to_features(self) -> None:
        """Alt+Shift+C: grab the drag-selected DNA *or* the highlighted feature
        from the main view, open the AddFeatureModal prefilled, and after
        Save transport the user to the FeatureLibraryScreen so they see the
        new entry in context.

        Priority:
          1. ``sp._user_sel`` (Shift+drag / Shift+arrow region / sidebar-click
             selection). If the range exactly matches one of ``pm._feats``,
             the prefill carries that feature's metadata (type, strand,
             color, qualifiers). Otherwise it's a raw DNA capture with
             generic ``misc_feature`` / strand=1 defaults.
          2. ``pm.selected_idx`` (feature clicked on map / sidebar with no
             active selection) — always full metadata.

        Insert-at-cursor is intentionally disabled for the capture workflow
        because the bases are already in the record."""
        try:
            sp = self.query_one("#seq-panel",   SequencePanel)
            pm = self.query_one("#plasmid-map", PlasmidMap)
        except NoMatches:
            return
        seq = sp._seq or ""
        if not seq:
            self.notify("No sequence loaded.", severity="warning")
            return

        prefill: "dict | None" = None

        if sp._user_sel is not None:
            s, e = sp._user_sel
            sub = seq[s:e].upper()
            if not sub:
                self.notify("Selection is empty.", severity="warning")
                return
            matched = -1
            for i, f in enumerate(pm._feats):
                if f.get("type") in ("resite", "recut"):
                    continue
                if (f.get("start"), f.get("end")) == (s, e):
                    matched = i
                    break
            if matched >= 0:
                prefill = self._prefill_from_feature(pm._feats[matched], seq)
            else:
                prefill = {
                    "name":         "",
                    "feature_type": "misc_feature",
                    "sequence":     sub,
                    "strand":       1,
                    "color":        None,
                    "qualifiers":   {},
                    "description":  f"Captured from bases {s + 1}..{e}",
                }
        elif 0 <= pm.selected_idx < len(pm._feats):
            feat = pm._feats[pm.selected_idx]
            if feat.get("type") in ("resite", "recut"):
                self.notify(
                    "Select a real feature (not a restriction site).",
                    severity="warning",
                )
                return
            prefill = self._prefill_from_feature(feat, seq)
        else:
            self.notify(
                "Select a feature (click the map) or Shift+drag a DNA region first.",
                severity="information",
            )
            return

        self.push_screen(
            AddFeatureModal(prefill=prefill),
            callback=self._capture_feature_result,
        )

    def _prefill_from_feature(self, feat: dict, seq: str) -> dict:
        """Build an AddFeatureModal prefill from a ``pm._feats`` entry. Pulls
        qualifiers from the matching SeqFeature on the current record so
        gene/product/note values ride along with the capture."""
        s, e = feat["start"], feat["end"]
        fwd_slice = (seq[s:] + seq[:e]) if (e < s) else seq[s:e]
        strand = feat.get("strand", 1)
        feat_seq = _rc(fwd_slice) if strand == -1 else fwd_slice
        quals: dict = {}
        if self._current_record is not None:
            total = len(seq)
            for bf in getattr(self._current_record, "features", []) or []:
                if bf.type != feat.get("type"):
                    continue
                # Route through `_feat_bounds` so a wrap CompoundLocation
                # doesn't flatten to (0, total) and silently miss the
                # match against the wrap dict-feature's (s, e) pair.
                # Pre-2026-05-11 used raw `int(bf.location.start)` which
                # Biopython returns as `min(part.start)` for a Compound —
                # zero for any canonical wrap — so the comparison
                # never fired and gene/product/note qualifiers dropped
                # silently from the prefill.
                bounds = _feat_bounds(bf, total)
                if bounds is None:
                    continue
                bs, be, _bf_strand = bounds
                if (bs, be) in ((s, e), (e, s)):
                    quals = {k: list(v) if isinstance(v, (list, tuple)) else [v]
                             for k, v in (bf.qualifiers or {}).items()}
                    break
        # The map palette uses Rich's ``color(N)`` syntax which round-trips
        # through Style.parse fine, but chokes Rich's markup lexer when
        # rewrapped as ``[color(N)]...[/]``. Convert to canonical hex on
        # capture so the stored library entry and every downstream preview
        # can use simple markup without escaping gymnastics.
        raw_color = feat.get("color")
        if isinstance(raw_color, str) and raw_color.startswith("color("):
            raw_color = _normalise_color_input(raw_color) or raw_color
        return {
            "name":         feat.get("label") or feat.get("type", ""),
            "feature_type": feat.get("type", "misc_feature"),
            "sequence":     feat_seq.upper(),
            "strand":       strand,
            "color":        raw_color,
            "qualifiers":   quals,
            "description":  "",
        }

    def _capture_feature_result(self, result) -> None:
        """Callback for the Alt+Shift+C capture flow. On Save, persist and push
        FeatureLibraryScreen. Insert is unreachable (have_cursor=False)."""
        if not result:
            return
        action = result.get("action")
        entry  = result.get("entry") or {}
        if action != "save":
            return
        if self._persist_feature_entry(entry):
            self._notify_success(f"Added '{entry.get('name')}' to feature library.")
            self.push_screen(FeatureLibraryScreen())

    @_action_log("app.feature.add")
    def action_add_feature(self) -> None:
        """Open the AddFeatureModal.

        If the user has a multi-bp selection (drag, Shift+click, or
        feature-pick), the modal opens with two affordances populated:

          1. Sequence body pre-filled with the highlighted bases
             verbatim — saves the typical "select → Ctrl+C → paste
             into modal" round-trip when only saving to the library.
          2. "Insert feature" button enabled, capturing the exact
             (start, end) range so the click annotates the existing
             bases base-perfect (no DNA spliced in).

        Without a selection, only "Save to Library" is functional —
        "Insert feature" is disabled with a tooltip explaining why.
        """
        sp = None
        try:
            sp = self.query_one("#seq-panel", SequencePanel)
        except NoMatches:
            sp = None
        prefill: "dict | None" = None
        sel_range: "tuple[int, int] | None" = None
        if sp is not None and sp._seq and self._current_record is not None:
            sel = sp._user_sel or sp._sel_range
            if sel is not None:
                s, e = sel
                n = len(sp._seq)
                # Wrap-aware span; only treat as a selection when more
                # than 1 bp is highlighted (single-base "selections"
                # come from a plain click and aren't really a region
                # the user would expect to annotate).
                span = _feat_len(s, e, n) if n else 0
                if span > 1:
                    if e >= s:
                        highlighted = sp._seq[s:e]
                    else:
                        # Wrap: tail [s, n) + head [0, e).
                        highlighted = sp._seq[s:] + sp._seq[:e]
                    prefill = {"sequence": highlighted.upper()}
                    sel_range = (s, e)
        # Sweep #21: guard against canvas reload mid-modal. The
        # "annotate" path embeds (start, end) coords from the
        # selection captured at modal-open time — applying those
        # to a NEW record's bases would silently corrupt the
        # annotation. Same rationale as `action_edit_seq` and
        # `_open_feature_editor`.
        self.push_screen(
            AddFeatureModal(prefill=prefill, selection_range=sel_range),
            callback=self._guard_callback(
                self._add_feature_result, "Add feature",
            ),
        )

    def _persist_feature_entry(self, entry: dict) -> bool:
        """Append `entry` to features.json, de-duping on (name, feature_type)
        so the latest write wins. Returns True on success; on failure, logs
        and notifies the user so callers can bail cleanly."""
        entries = _load_features()
        key = (entry.get("name"), entry.get("feature_type"))
        entries = [e for e in entries
                   if (e.get("name"), e.get("feature_type")) != key]
        entries.append(entry)
        try:
            _save_features(entries)
        except (OSError, RuntimeError) as exc:
            _notify_save_failure(self.app, "Feature library", exc)
            return False
        return True

    def _add_feature_result(self, result) -> None:
        """Callback for AddFeatureModal. `result` is either None (cancel) or
        ``{"action": "save"|"annotate", "entry": {...}, "range": (s, e)?}``.

        - ``save``: persist the feature dict to the user's feature library.
        - ``annotate``: add a SeqFeature to the loaded record, spanning the
          (start, end) range from the modal's captured selection. Does NOT
          modify the underlying DNA — the new feature annotates existing
          bases base-perfect.
        """
        if not result:
            return
        action = result.get("action")
        entry  = result.get("entry") or {}
        if action == "save":
            if self._persist_feature_entry(entry):
                self._notify_success(f"Saved '{entry.get('name')}' to feature library.")
            return
        if action == "annotate":
            sel_range = result.get("range")
            if not sel_range or len(sel_range) != 2:
                self.notify("No selection to annotate.", severity="warning")
                return
            try:
                start, end = int(sel_range[0]), int(sel_range[1])
                self._annotate_with_feature(start, end, entry)
            except (ValueError, RuntimeError) as exc:
                _log.exception("Failed to annotate selection with feature")
                self.notify(f"Annotate failed: {exc}", severity="error")

    def _annotate_with_feature(
        self, start: int, end: int, entry: dict,
    ) -> None:
        """Add a SeqFeature spanning ``[start, end)`` to the loaded
        record without modifying the underlying DNA.

        Wrap-aware: when ``end < start``, the location becomes a
        CompoundLocation with two parts (tail [start, n) + head
        [0, end)) so origin-spanning annotations land correctly. The
        new feature joins ``record.features`` and goes through the
        same lane-packing pipeline as every other feature, so it
        stacks with normal priority in the lane art.

        Used by both the AddFeatureModal "Insert feature" button and
        the agent-API ``add-feature`` endpoint — single source of
        truth for "annotate existing bases".
        """
        _log_event(
            "annotate.start", start=start, end=end,
            type=entry.get("feature_type"),
            label=entry.get("name"),
            strand=entry.get("strand"),
            is_group=bool(entry.get("is_group")),
            n_members=(len(entry.get("members") or [])
                        if entry.get("is_group") else 0),
        )
        with _log_timing("app.annotate_with_feature"):
            # Group entries spawn N sub-features sharing a
            # `feature_group` qualifier (sweep #29). Detection key
            # is the `is_group=True` flag AND a non-empty `members`
            # list — see `_is_group_entry` for the back-compat
            # rationale. A malformed `is_group=True` entry with no
            # members falls through to the single-feature path so
            # users at least see SOMETHING land rather than a
            # silent no-op.
            if _is_group_entry(entry):
                self._annotate_with_feature_group_impl(
                    start, end, entry,
                )
            else:
                self._annotate_with_feature_impl(start, end, entry)
        _log_event(
            "annotate.done", n_feats=len(self._current_record.features)
                              if self._current_record else 0,
        )

    def _annotate_with_feature_impl(
        self, start: int, end: int, entry: dict,
    ) -> None:
        from Bio.SeqFeature import SeqFeature, FeatureLocation, CompoundLocation

        if self._current_record is None:
            raise RuntimeError("Load a plasmid first.")
        n = _seq_len(self._current_record)
        if not (0 <= start < n):
            raise ValueError(f"start {start} out of range [0, {n})")
        if not (0 <= end <= n):
            raise ValueError(f"end {end} out of range [0, {n}]")
        if end == start:
            raise ValueError("zero-length feature (end == start)")

        # CDS divisible-by-3 gate. The modal blocks this earlier with
        # an inline error; the helper repeats the check so direct
        # callers (agent-API `add-feature`, future programmatic
        # entry points) can't bypass it. Wrap-aware via `_feat_len`.
        feat_type = entry.get("feature_type") or "misc_feature"
        if feat_type == "CDS":
            span = _feat_len(start, end, n)
            if span % 3 != 0:
                raise ValueError(
                    f"CDS must span a whole number of codons "
                    f"({span} bp is not divisible by 3)."
                )

        raw_strand = entry.get("strand", 1)
        try:
            strand = int(raw_strand)
        except (TypeError, ValueError):
            strand = 1
        if strand not in (-1, 0, 1, 2):
            strand = 1
        # `2` (double-stranded) is a SpliceCraft-only convention; map
        # to None on the BioPython side since CompoundLocation parts
        # require ±1 / 0 / None.
        biop_strand = strand if strand in (-1, 1) else None
        if end > start:
            loc = FeatureLocation(start, end, strand=biop_strand)
        else:
            loc = CompoundLocation([
                FeatureLocation(start, n, strand=biop_strand),
                FeatureLocation(0, end, strand=biop_strand),
            ])
        qualifiers: dict = {
            k: list(v) if isinstance(v, (list, tuple)) else [v]
            for k, v in (entry.get("qualifiers") or {}).items()
        }
        label = (entry.get("name") or "").strip()
        if label and "label" not in qualifiers:
            qualifiers["label"] = [label]
        # Double-stranded (`◀…▶`) is a SpliceCraft-only convention
        # that BioPython's strand can't represent (it only accepts
        # ±1 / 0 / None — `biop_strand` was already mapped to None
        # for strand=2 above). Persist via a SpliceCraft-internal
        # qualifier so `PlasmidMap._parse` can restore strand=2 on
        # reload; absence of the qualifier means the standard
        # BioPython interpretation. Stays sibling to `label` so
        # programmatic / agent-API callers can read either.
        if strand == 2:
            qualifiers["SpliceCraft_strand"] = ["double"]
        # Color: persist via the same `ApEinfo_fwdcolor` /
        # `ApEinfo_revcolor` qualifiers CommercialSaaS/Benchling use
        # so the choice round-trips through `.gb` export AND so the
        # in-app feature-color resolver (`_resolve_feature_color`)
        # picks it up at render time. Pre-2026-05-26 the entry dict
        # carried `entry["color"]` from the AddFeature/Insert flow's
        # color picker but `_annotate_with_feature_impl` never wrote
        # it onto the SeqFeature — user picked a color, the
        # AddFeature modal's swatch updated, but the bar in the seq
        # panel / map stayed on the type-default color
        # (user-reported: "choosing color does not seem to apply
        # that color to the feature"). Mirrors the
        # `_apply_feature_edit` path so create + edit stay
        # symmetric.
        new_color = entry.get("color")
        if isinstance(new_color, str) and new_color.strip():
            normalized = new_color.strip()
            qualifiers["ApEinfo_fwdcolor"] = [normalized]
            qualifiers["ApEinfo_revcolor"] = [normalized]
        new_feat = SeqFeature(loc, type=feat_type, qualifiers=qualifiers)

        # Snapshot pre-edit so the user can Ctrl+Z. Then mutate a
        # deep copy so existing references (undo stack, agent reads)
        # don't see torn state.
        self._push_undo()
        new_record = deepcopy(self._current_record)
        new_record.features.append(new_feat)
        self._current_record = new_record

        # Mirror the panel-refresh block used by other in-place edits
        # (avoids `_apply_record`'s "Loaded …" toast + mark-clean).
        pm      = self.query_one("#plasmid-map", PlasmidMap)
        sidebar = self.query_one("#sidebar",     FeatureSidebar)
        sp      = self.query_one("#seq-panel",   SequencePanel)
        pm.load_record(new_record)
        seq_str = str(new_record.seq)
        # Restriction scan dispatched async — `_dispatch_restr_scan` paints
        # overlays when the worker reports. Pre-fix the synchronous call
        # here hitched the Add-Feature modal close on big plasmids.
        self._restr_cache = []
        pm._restr_feats = []
        pm.refresh()
        sidebar.populate(pm._feats)
        sp.update_seq(seq_str, pm._feats)
        self._dispatch_restr_scan(seq_str)
        # Auto-highlight the freshly-annotated bp range. `update_seq`
        # cleared `_user_sel`; setting it now to the new feature's
        # span paints the white-on-black overlay on those bases the
        # moment the modal closes — the user sees confirmation of
        # what was added AND can locate the bar (which sits at the
        # top of the lane stack with insertion-order packing) by
        # following the highlighted bp range.
        # Don't move `_cursor_pos` — the new feature ADDS a row to
        # the lane stack which already shifts the DNA strand down
        # by one row. Forcing the cursor to the feature's start on
        # top of that compounds the visible "jump" and disorients
        # the user. The highlight alone is the cue they need.
        sp._user_sel  = (start, end)
        sp._sel_range = None
        sp._sel_anchor = start
        sp._refresh_view()
        # Map / sidebar should also reflect the new selection.
        # `pm` / `sidebar` are typed `query_one` results already used
        # unguarded above; `select_feature` / `highlight_row` are
        # index-safe for a bounds-checked idx — no try/except needed.
        # The bounds check still defends the empty-feats case
        # (new_idx == -1 when a parse yields zero features).
        new_idx = len(pm._feats) - 1
        if 0 <= new_idx < len(pm._feats):
            pm.select_feature(new_idx)
            sidebar.highlight_row(new_idx)
        self._mark_dirty()

        coord_str = (f"{start + 1}..{end}" if end > start
                     else f"{start + 1}..{n},1..{end}")
        span = (end - start) if end > start else (n - start) + end
        self._notify_success(
            f"Annotated {feat_type} "
            f"'{label or '(unlabeled)'}' at {coord_str} ({span} bp)."
        )

    def _annotate_with_feature_group_impl(
        self, start: int, end: int, entry: dict,
    ) -> None:
        """Sweep #29 — atomically annotate the N sub-features of a
        group library entry. The selection span `[start, end)` (the
        canvas region the user is anchoring the group to) must
        match the group's `sequence` length exactly; the rel coords
        of each member then land at `[start + rel_start, start +
        rel_end)` with circular-wrap handling via modular
        arithmetic. All members are stamped with a single fresh
        `feature_group` qualifier (12-char uuid hex) so the UI can
        cascade operations (delete-group, ungroup, rename-group).

        Sacred invariant care:
          * #5 / #8: `_feat_len(start, end, n)` for the span check
            so a wrap selection (end < start) compares against the
            wrap-aware length, not `end - start` which is negative.
          * #9: per-member wrap detection — if a member's raw end
            crosses the origin (`start + rel_end > n`) on a circular
            plasmid, build a `CompoundLocation` with two parts so
            `_feat_bounds` re-extracts the right `(tail_start,
            head_end)` shape on the next `_parse`. Linear plasmids
            refuse a would-wrap member with a clear ValueError.
          * #10: undo snapshot deepcopied via `_push_undo` BEFORE
            the mutation so Ctrl+Z reverts the whole group atomically.
          * One `_mark_dirty` for the whole transaction.

        Color / strand / SpliceCraft_strand qualifiers persist
        per-member (mirrors `_annotate_with_feature_impl`), so
        each sub-feature renders with its own colour + arrow type
        and round-trips through save/load."""
        from Bio.SeqFeature import (
            SeqFeature, FeatureLocation, CompoundLocation,
        )
        if self._current_record is None:
            raise RuntimeError("Load a plasmid first.")
        n = _seq_len(self._current_record)
        if n <= 0:
            raise RuntimeError("Loaded record has zero length.")
        # Topology — circular plasmids allow wrap; linear refuses.
        try:
            topology = str(
                self._current_record.annotations.get("topology")
                or "linear",
            ).strip().lower()
        except AttributeError:
            topology = "linear"
        is_circular = (topology == "circular")
        # Validate the group's members against its declared
        # sequence length. Defence-in-depth: callers may hand a
        # malformed entry, and we want the error here, not deep in
        # the SeqFeature constructor stack.
        seq_str = str(entry.get("sequence") or "")
        seq_len = len(seq_str)
        if seq_len < 1:
            raise ValueError(
                "group entry has empty sequence — cannot determine "
                "member ranges"
            )
        try:
            members = _validate_group_members(
                entry.get("members") or [], seq_len,
            )
        except ValueError as exc:
            raise ValueError(
                f"group entry '{entry.get('name')!r}': {exc}"
            )
        # Selection span check. `_feat_len` gives the wrap-aware
        # length (= `(n - start) + end` when `end < start`,
        # otherwise `end - start`).
        if not (0 <= start < n):
            raise ValueError(f"start {start} out of range [0, {n})")
        if not (0 <= end <= n):
            raise ValueError(f"end {end} out of range [0, {n}]")
        if end == start:
            raise ValueError(
                "zero-length selection — cannot place group"
            )
        span = _feat_len(start, end, n)
        if span != seq_len:
            raise ValueError(
                f"selection span ({span} bp) does not match group "
                f"sequence length ({seq_len} bp); select exactly "
                f"the bases the group should cover"
            )
        # CDS divisible-by-3 gate per member (mirrors the single-
        # feature path). The constructor enforces this so the
        # group can't smuggle a partial-codon CDS past the check.
        for m in members:
            if m["feature_type"] == "CDS":
                m_span = m["rel_end"] - m["rel_start"]
                if m_span % 3 != 0:
                    raise ValueError(
                        f"member '{m['label']}' is CDS but spans "
                        f"{m_span} bp (not a whole codon multiple)"
                    )
        # Wrap-feasibility check: a linear plasmid can't host a
        # member whose absolute end exceeds `n`.
        for m in members:
            raw_end = start + m["rel_end"]
            if not is_circular and raw_end > n:
                raise ValueError(
                    f"member '{m['label']}' would land at bp "
                    f"{raw_end}, past the linear plasmid end "
                    f"({n}). Insert into a circular plasmid or "
                    f"shorten the group."
                )
        # All checks green — mutate. Snapshot for undo, deepcopy
        # the record, build + append each SeqFeature, then refresh.
        self._push_undo()
        new_record = deepcopy(self._current_record)
        from uuid import uuid4
        group_id = uuid4().hex[:12]
        landed: "list[tuple[str, int, int]]" = []
        for m in members:
            raw_s = start + m["rel_start"]
            raw_e = start + m["rel_end"]
            # Modular wrap (only meaningful for circular). For
            # linear we already refused over-end members above.
            # A member STRADDLES the origin iff raw_s < n < raw_e
            # — its start is before the origin and its end is
            # past. A member FULLY past the origin (raw_s > n)
            # lands as a plain FeatureLocation at the modular
            # coords; only the straddle case needs a
            # CompoundLocation. End-falls-exactly-on-origin
            # (raw_e == n, after a `member_wraps` check that
            # excludes the n boundary) renders as plain too.
            if is_circular and n > 0:
                abs_s = raw_s % n
                abs_e = raw_e % n
                # End falling exactly on the origin = full-length
                # member ending at n, NOT a 0-bp wrap. Pin to n
                # so the renderer doesn't treat it as a zero-bp
                # head fragment.
                if raw_e > 0 and raw_e % n == 0:
                    abs_e = n
                member_wraps = (raw_s < n < raw_e)
            else:
                abs_s = raw_s
                abs_e = raw_e
                member_wraps = False
            biop_strand = (
                m["strand"] if m["strand"] in (-1, 1) else None
            )
            if member_wraps:
                loc = CompoundLocation([
                    FeatureLocation(abs_s, n, strand=biop_strand),
                    FeatureLocation(0, abs_e, strand=biop_strand),
                ])
            else:
                loc = FeatureLocation(
                    abs_s, abs_e, strand=biop_strand,
                )
            quals: dict = {
                k: list(v) if isinstance(v, (list, tuple)) else [v]
                for k, v in (m["qualifiers"] or {}).items()
            }
            label = (m["label"] or "").strip()
            if label and "label" not in quals:
                quals["label"] = [label]
            color = m["color"]
            if isinstance(color, str) and color.strip():
                normalized = color.strip()
                quals["ApEinfo_fwdcolor"] = [normalized]
                quals["ApEinfo_revcolor"] = [normalized]
            if m["strand"] == 2:
                quals["SpliceCraft_strand"] = ["double"]
            quals["feature_group"] = [group_id]
            new_record.features.append(SeqFeature(
                loc, type=m["feature_type"], qualifiers=quals,
            ))
            landed.append((
                label or m["feature_type"], abs_s, abs_e,
            ))
        self._current_record = new_record
        # Refresh panels (same block as `_annotate_with_feature_impl`).
        pm      = self.query_one("#plasmid-map",  PlasmidMap)
        sidebar = self.query_one("#sidebar",      FeatureSidebar)
        sp      = self.query_one("#seq-panel",    SequencePanel)
        pm.load_record(new_record)
        seq_render = str(new_record.seq)
        self._restr_cache = []
        pm._restr_feats = []
        pm.refresh()
        sidebar.populate(pm._feats)
        sp.update_seq(seq_render, pm._feats)
        self._dispatch_restr_scan(seq_render)
        # Highlight the whole group span — same UX as a single-
        # feature annotation, just covering the wrap-aware range.
        sp._user_sel  = (start, end)
        sp._sel_range = None
        sp._sel_anchor = start
        sp._refresh_view()
        # Sidebar / map: focus the LAST landed member so the
        # cursor sits on the most-recently-added bar (matches the
        # single-feature path's "select the just-added feature"
        # behaviour). The other members are accessible via
        # sidebar arrow keys.
        # Same index-safe selection sync as the single-feature
        # annotate path — typed `query_one` widgets + bounds-checked
        # idx mean neither IndexError nor AttributeError can fire.
        new_idx = len(pm._feats) - 1
        if 0 <= new_idx < len(pm._feats):
            pm.select_feature(new_idx)
            sidebar.highlight_row(new_idx)
        self._mark_dirty()
        # Compact summary toast — the user just inserted N
        # features; itemising every label would balloon the toast.
        name = (entry.get("name") or "").strip() or "(unnamed group)"
        self._notify_success(
            f"Annotated group '{name}' ({len(landed)} sub-features, "
            f"{span} bp) — group_id={group_id[:8]}…"
        )

    # ── Sweep #29: group operations on canvas features ──────────────

    def _set_feature_group(
        self, idx_list: "list[int]",
        group_id: "str | None" = None,
    ) -> "str | None":
        """Stamp the given feature indices on the currently-loaded
        record with a shared `feature_group=<group_id>` qualifier
        so the UI can cascade operations (delete-group,
        ungroup, future "select all members" actions).

        `idx_list` indexes into the canonical `PlasmidMap._feats`
        list (which excludes the synthetic `source` feature), so
        the helper must walk `record.features` skipping `source`
        entries to align indices — matches `_apply_feature_edit`'s
        traversal.

        If `group_id` is None, a fresh 12-char uuid hex prefix is
        minted. Returns the group id used (so callers can confirm /
        log). Returns None when no features were stamped (empty
        list, all indices out of range, etc.) — caller should
        treat that as a no-op.

        Idempotent: stamping a feature that already has the same
        `feature_group` qualifier is a no-op write. Stamping a
        feature with a DIFFERENT group_id REPLACES the qualifier
        (the most-recent group wins; the previous group keeps its
        other members but loses this one)."""
        if not idx_list or self._current_record is None:
            return None
        from uuid import uuid4
        gid = group_id or uuid4().hex[:12]
        wanted = set(int(i) for i in idx_list if isinstance(i, int))
        if not wanted:
            return None
        self._push_undo()
        new_record = deepcopy(self._current_record)
        seen = 0
        stamped = 0
        for f in new_record.features:
            if f.type == "source":
                continue
            if seen in wanted:
                f.qualifiers["feature_group"] = [gid]
                stamped += 1
            seen += 1
        if stamped == 0:
            return None
        self._current_record = new_record
        self._refresh_panels_after_mutation()
        self._mark_dirty()
        _log_event(
            "feature.group.set",
            group_id=gid, n_stamped=stamped,
            n_requested=len(wanted),
        )
        return gid

    def _clear_feature_group(
        self, idx_list: "list[int]",
    ) -> int:
        """Drop the `feature_group` qualifier from the given
        feature indices. Returns the count of features that
        actually had a qualifier removed (so the caller can
        notify the user). Idempotent: features without a
        qualifier are unchanged."""
        if not idx_list or self._current_record is None:
            return 0
        wanted = set(int(i) for i in idx_list if isinstance(i, int))
        if not wanted:
            return 0
        self._push_undo()
        new_record = deepcopy(self._current_record)
        seen = 0
        cleared = 0
        for f in new_record.features:
            if f.type == "source":
                continue
            if seen in wanted and "feature_group" in f.qualifiers:
                del f.qualifiers["feature_group"]
                cleared += 1
            seen += 1
        if cleared == 0:
            return 0
        self._current_record = new_record
        self._refresh_panels_after_mutation()
        self._mark_dirty()
        _log_event(
            "feature.group.clear", n_cleared=cleared,
        )
        return cleared

    def _refresh_panels_after_mutation(self) -> None:
        """Helper: re-load record into PlasmidMap + SequencePanel +
        FeatureSidebar after a record mutation (group / ungroup /
        any other operation that doesn't change the bp coords).
        Extracts the panel-refresh block used by
        `_annotate_with_feature_impl` so group ops can share it
        without duplicating the body."""
        if self._current_record is None:
            return
        try:
            pm = self.query_one("#plasmid-map", PlasmidMap)
            sidebar = self.query_one("#sidebar", FeatureSidebar)
            sp = self.query_one("#seq-panel", SequencePanel)
        except NoMatches:
            return
        pm.load_record(self._current_record)
        seq_str = str(self._current_record.seq)
        self._restr_cache = []
        pm._restr_feats = []
        pm.refresh()
        sidebar.populate(pm._feats)
        sp.update_seq(seq_str, pm._feats)
        self._dispatch_restr_scan(seq_str)

    def _feature_group_id(
        self, feat: "dict | None",
    ) -> "str | None":
        """Return the `feature_group` qualifier value for a feat
        dict (from `PlasmidMap._feats`), or None when the feat
        isn't grouped. Defensive: the dict may not carry the
        underlying SeqFeature's qualifiers — we re-read from
        `self._current_record.features` to get the canonical
        value if needed."""
        if not isinstance(feat, dict):
            return None
        # Some _feats dicts copy qualifiers; many don't. Walk
        # record.features by start coord as a fallback.
        if self._current_record is None:
            return None
        try:
            f_start = int(feat.get("start", -1))
            f_end = int(feat.get("end", -1))
            f_label = str(feat.get("label", "") or "")
        except (TypeError, ValueError):
            return None
        for sf in self._current_record.features:
            if sf.type == "source":
                continue
            loc = getattr(sf, "location", None)
            if loc is None:
                continue
            try:
                s = int(loc.start)
                e = int(loc.end)
            except (TypeError, ValueError, AttributeError):
                continue
            if s == f_start and e == f_end:
                lbl = sf.qualifiers.get("label", [""])[0]
                if str(lbl) == f_label:
                    fg = sf.qualifiers.get("feature_group")
                    if isinstance(fg, list) and fg:
                        return str(fg[0])
        return None

    def _features_in_group(
        self, group_id: str,
    ) -> "list[int]":
        """Return the list of `PlasmidMap._feats` indices whose
        underlying SeqFeature carries `feature_group == group_id`.
        Walks `record.features` in order, skipping `source`."""
        if self._current_record is None or not group_id:
            return []
        out: list[int] = []
        seen = 0
        for f in self._current_record.features:
            if f.type == "source":
                continue
            fg = f.qualifiers.get("feature_group")
            if (isinstance(fg, list) and fg
                    and str(fg[0]) == group_id):
                out.append(seen)
            seen += 1
        return out

    def _save_features_as_group_entry(
        self, name: str, idx_list: "list[int]",
    ) -> bool:
        """Snapshot the given features into a single group-style
        library entry and persist via `_save_features`. Returns
        True on success.

        Anchor + member coords: the leftmost feature's start is
        the anchor; each member's `rel_start` / `rel_end` are
        computed relative to the anchor. Wrap-spanning groups are
        NOT supported in this version (the user can ungroup,
        rotate the plasmid so the group is contiguous, then save
        as a group entry — keeps the math straightforward).

        Sequence: extracted from the loaded record's bases at
        `[anchor, max_end)`. The caller is responsible for ensuring
        the group is contiguous on the same linear strand — wrap
        groups raise ValueError."""
        if self._current_record is None:
            raise RuntimeError("Load a plasmid first.")
        nm = (name or "").strip()
        if not nm:
            raise ValueError("group library entry name must be non-empty")
        wanted = sorted(set(int(i) for i in idx_list
                              if isinstance(i, int)))
        if not wanted:
            raise ValueError("no features selected to group-save")
        # Collect the SeqFeatures at those indices.
        feats_by_idx: dict = {}
        seen = 0
        for f in self._current_record.features:
            if f.type == "source":
                continue
            if seen in wanted:
                feats_by_idx[seen] = f
            seen += 1
        if len(feats_by_idx) != len(wanted):
            raise ValueError(
                f"some indices out of range "
                f"(requested {len(wanted)}, found {len(feats_by_idx)})"
            )
        # Determine anchor + max_end. Refuse wrap features for now
        # (member rel coords don't have a clean mapping when the
        # group itself spans the origin).
        n = _seq_len(self._current_record)
        starts: list[int] = []
        ends: list[int] = []
        for f in feats_by_idx.values():
            from Bio.SeqFeature import CompoundLocation
            if isinstance(f.location, CompoundLocation):
                raise ValueError(
                    f"feature '{f.qualifiers.get('label', ['?'])[0]}' "
                    f"spans the origin (CompoundLocation) — "
                    f"rotate the plasmid so the group is contiguous "
                    f"before saving as a library entry"
                )
            try:
                starts.append(int(f.location.start))
                ends.append(int(f.location.end))
            except (TypeError, ValueError):
                raise ValueError(
                    "feature has non-integer coordinates "
                    "(UnknownPosition / BetweenPosition); cannot "
                    "compute rel coords"
                )
        anchor = min(starts)
        max_end = max(ends)
        if not (0 <= anchor < max_end <= n):
            raise ValueError(
                f"computed group span [{anchor}, {max_end}) is "
                f"out of range [0, {n}]"
            )
        # Extract the group's sequence from the record.
        seq_str = str(self._current_record.seq)[anchor:max_end]
        # Build members list with rel coords.
        members: list[dict] = []
        for f in sorted(
            feats_by_idx.values(),
            key=lambda f: (int(f.location.start), int(f.location.end)),
        ):
            s = int(f.location.start)
            e = int(f.location.end)
            label = ""
            lbl_q = f.qualifiers.get("label")
            if isinstance(lbl_q, list) and lbl_q:
                label = str(lbl_q[0])
            # Color: prefer ApEinfo_fwdcolor, fall back to existing
            # qualifiers, else None (palette fallback at render).
            color: "str | None" = None
            for k in ("ApEinfo_fwdcolor", "ApEinfo_revcolor", "color"):
                v = f.qualifiers.get(k)
                if isinstance(v, list) and v:
                    c = str(v[0]).strip()
                    if c.startswith("#") and len(c) in (4, 7):
                        color = c
                        break
            # Strand: BioPython ±1 / None → SpliceCraft dict ±1 / 0,
            # with SpliceCraft_strand qualifier promoting to 2.
            raw_strand = getattr(f.location, "strand", None)
            strand = int(raw_strand) if raw_strand is not None else 0
            sc_strand_q = f.qualifiers.get("SpliceCraft_strand")
            if (isinstance(sc_strand_q, list) and sc_strand_q
                    and str(sc_strand_q[0]).strip().lower()
                        == "double"):
                strand = 2
            # Strip group / SpliceCraft-internal / color qualifiers
            # from the member's saved qualifiers — those are stamped
            # again at annotate-time by the group helper. Keeping
            # them would shadow the user's eventual edits.
            member_quals = {
                k: list(v) if isinstance(v, (list, tuple)) else [v]
                for k, v in f.qualifiers.items()
                if k not in (
                    "feature_group", "SpliceCraft_strand",
                    "ApEinfo_fwdcolor", "ApEinfo_revcolor", "color",
                    "label",
                )
            }
            members.append({
                "rel_start":    s - anchor,
                "rel_end":      e - anchor,
                "feature_type": f.type,
                "label":        label,
                "color":        color,
                "strand":       strand,
                "qualifiers":   member_quals,
                "description": "",
            })
        # Sanity-validate before persisting (catches any
        # accidentally-built bad member dict).
        _validate_group_members(members, len(seq_str))
        entry: dict = {
            "name":         nm,
            "sequence":     seq_str.upper(),
            "feature_type": "misc_feature",   # placeholder for legacy readers
            "strand":       1,                # placeholder
            "is_group":     True,
            "members":      members,
            "qualifiers":   {},
            "description":  (
                f"Group of {len(members)} sub-features "
                f"({len(seq_str)} bp). Generated by SpliceCraft."
            ),
        }
        entries = _load_features()
        # De-dupe on (name, is_group=True) — latest write wins.
        entries = [
            e for e in entries
            if not (e.get("name") == nm and e.get("is_group"))
        ]
        entries.append(entry)
        _save_features(entries)
        _log_event(
            "feature.group.saved_as_library_entry",
            name=nm, n_members=len(members), bp=len(seq_str),
        )
        return True

    @_action_log("app.open.parts_bin")
    def action_open_parts_bin(self) -> None:
        """Open the parts toolbar tab.

        Two-step flow: first push `PartsBinPickerModal` so the user
        picks (or creates / renames / duplicates / deletes) a parts
        bin; on dismiss with a bin name, the picker has already set
        it active and we push the existing `PartsBinModal` against
        the active bin. Cancel / Close from the picker = no-op.

        The migration in `compose()` (`_ensure_default_parts_bin`)
        guarantees at least one bin exists, so the picker always has
        something to show — first-run users see "Main Parts Bin"
        wrapping any pre-existing `parts_bin.json` contents.
        """
        def _on_picked(bin_name):
            if not bin_name:
                return
            self.push_screen(PartsBinModal())
        self.push_screen(PartsBinPickerModal(), callback=_on_picked)

    @_action_log("app.open.collections")
    def action_open_collections(self) -> None:
        """Open the plasmid-collections manager."""
        self.push_screen(CollectionsModal(),
                         callback=self._on_collections_dismissed)

    def _on_collections_dismissed(self, result) -> None:
        """If a collection was loaded, replace the current library wholesale
        and refresh the panel into the plasmids view of the new collection.
        Keep the active record (the user might be editing) — they can
        switch via the panel if needed."""
        if not isinstance(result, dict) or not result.get("loaded"):
            return
        try:
            panel = self.query_one("#library", LibraryPanel)
            panel._view_mode = "plasmids"
            panel._apply_view_mode()
            panel._repopulate()
        except NoMatches:
            pass
        self.notify(
            f"Loaded collection '{result['loaded']}' "
            f"({result['n_plasmids']} plasmid(s)). "
            f"Previous library backed up to plasmid_library.json.bak.",
            timeout=10,
        )

    @_action_log("app.open.constructor")
    def action_open_constructor(self) -> None:
        self.push_screen(ConstructorModal())

    @_action_log("app.open.grammars")
    def action_open_grammars(self) -> None:
        """Settings → Cloning grammars… opens the grammar manager so
        the user can create / edit / delete custom grammars without
        touching `cloning_grammars.json` by hand. Custom grammars
        appear automatically in every grammar dropdown
        (`_grammar_dropdown_options`) once saved."""
